class SaldoInsuficiente extends Exception {
    SaldoInsuficiente(String mensaje) { super(mensaje); }
}

class Main {
    static void retirar(double saldo, double cantidad) throws SaldoInsuficiente {
        if (cantidad > saldo) throw new SaldoInsuficiente("Faltan " + (cantidad - saldo) + " euros");
    }
    public static void main(String[] args) {
        try {
            retirar(50, 80);
        } catch (SaldoInsuficiente e) {
            System.out.println(e.getMessage());
        }
    }
}

